import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-BsOuDHI-.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/multi-tenancy.html","title":"Multi-Tenancy","lang":"en-US","frontmatter":{"title":"Multi-Tenancy"},"git":{"updatedTime":1788441191000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5.1","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"8dee9f767ead84b6e47c023533864d1d3e3178ae","time":1788441191000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"The release post carries the day 4.0.0 shipped","coAuthors":[{"name":"Claude Fable 5.1","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/multi-tenancy.md"}`),u={name:`multi-tenancy.md`},d={class:`hint-container warning`};function f(s,l,u,f,p,m){let h=a(`RouteLink`);return n(),o(`div`,null,[l[55]||=e(`h1`,{id:`multi-tenancy`,tabindex:`-1`},[e(`a`,{class:`header-anchor`,href:`#multi-tenancy`},[e(`span`,null,`Multi-Tenancy`)])],-1),l[56]||=e(`p`,null,[r(`Quartz has no `),e(`code`,null,`Tenant`),r(` concept, and it is not going to get one. What it has instead are three separations you can build one out of — a scheduler, a group, and a `),e(`code`,null,`SCHED_NAME`),r(` — and this page is about picking the right one and knowing exactly what it does and does not isolate.`)],-1),e(`p`,null,[l[1]||=r(`If you have not yet chosen a model, read `,-1),c(h,{to:`/documentation/tenancy-patterns.html`},{default:i(()=>[...l[0]||=[r(`Tenancy Patterns`,-1)]]),_:1}),l[2]||=r(` first: it surveys how other schedulers partition tenants and names the axes that decide. This page is the 4.x mechanics.`,-1)]),l[57]||=t(`<h2 id="choosing-a-model" tabindex="-1"><a class="header-anchor" href="#choosing-a-model"><span>Choosing a model</span></a></h2><table><thead><tr><th></th><th>Scheduler per tenant</th><th>Group per tenant</th><th>Database or prefix per tenant</th></tr></thead><tbody><tr><td><strong>Isolation</strong></td><td>strongest: separate job store, thread pool, clock, listeners</td><td>logical only — one scheduler, one pool</td><td>strongest at rest; one process still runs them all</td></tr><tr><td><strong>Tenants known at</strong></td><td>startup</td><td>any time</td><td>startup</td></tr><tr><td><strong>Add a tenant at runtime</strong></td><td>no (needs a new container)</td><td>yes</td><td>no</td></tr><tr><td><strong>Per-tenant concurrency limits</strong></td><td>yes, naturally</td><td>yes, via execution groups</td><td>yes</td></tr><tr><td><strong>Per-tenant dashboard and API access</strong></td><td>yes — <a href="#authorizing-a-tenant-on-its-own-scheduler"><code>SchedulerAuthorizationPolicy</code></a></td><td>no: Quartz authorizes a scheduler, not a group</td><td>yes, if each is its own scheduler</td></tr><tr><td><strong>Cost per tenant</strong></td><td>a scheduling loop, a connection pool, a thread pool</td><td>~nothing</td><td>a schema</td></tr><tr><td><strong>Fits</strong></td><td>tens of tenants, strong isolation needs</td><td>hundreds or thousands of tenants</td><td>regulatory separation of data</td></tr></tbody></table><p>They compose. The common shape for a SaaS with many small tenants is <em>one</em> scheduler, groups per tenant, one database — and a second scheduler for the handful of tenants that bought isolation.</p><p>The question that usually decides it: <strong>can a tenant appear while the process is running?</strong> If yes, the scheduler-per-tenant model is out, because a scheduler cannot be added to a container that has already been built.</p><h2 id="scheduler-per-tenant" tabindex="-1"><a class="header-anchor" href="#scheduler-per-tenant"><span>Scheduler per tenant</span></a></h2><p><code>AddQuartz(name, …)</code> registers a named scheduler. The name is its instance name, the key its components are registered under, and the name of its options — so its registrations and its configuration always agree.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> tenant <span class="token keyword">in</span> tenants<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>tenant<span class="token punctuation">,</span> q <span class="token operator">=&gt;</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span>connectionStrings<span class="token punctuation">[</span>tenant<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            s<span class="token punctuation">.</span><span class="token function">UseClustering</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token function">UseDefaultThreadPool</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrency</span><span class="token punctuation">:</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>NightlyReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddTrigger</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>NightlyReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t<span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 30 2 * * ?&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartzHostedService</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>WaitForJobsToComplete <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>One <code>AddQuartzHostedService</code> starts them all. Calling the named overload — <code>AddQuartzHostedService(tenant, o =&gt; …)</code> — configures <em>that</em> scheduler&#39;s start options and still registers only one hosted service; two would each start every scheduler in the container.</p><h3 id="starting-and-stopping-all-of-them" tabindex="-1"><a class="header-anchor" href="#starting-and-stopping-all-of-them"><span>Starting and stopping all of them</span></a></h3><p>The hosted service builds every scheduler in the container while the host starts, and then starts them: immediately under <code>AwaitApplicationStarted = false</code>, and otherwise — which is the default — once <code>ApplicationStarted</code> fires. So a tenant&#39;s scheduler exists before the application runs and is firing shortly after it does.</p><p>Two things about that follow the tenant count rather than the code:</p><ul><li><strong>A start that fails takes the tenants already created down with it.</strong> The schedulers built before the failure are already bound to the repository, so the hosted service shuts them down before it rethrows rather than leaving them running with nothing left to stop them.</li><li><strong>Shutdown is one deadline for every tenant, not one each.</strong> The schedulers are shut down concurrently, so <code>HostOptions.ShutdownTimeout</code> bounds the whole set — with <code>WaitForJobsToComplete = true</code> the host waits as long as the slowest tenant&#39;s jobs take, not as long as all of them added together. Each scheduler owns its own thread pool, job store and scheduler thread, so there is nothing for them to serialize behind.</li></ul><h3 id="injecting-one" tabindex="-1"><a class="header-anchor" href="#injecting-one"><span>Injecting one</span></a></h3><p>A named scheduler is keyed by its name:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TenantOpsService</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token attribute"><span class="token class-name">FromKeyedServices</span><span class="token attribute-arguments"><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">)</span></span></span><span class="token punctuation">]</span> <span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">IScheduler</span> scheduler <span class="token operator">=</span> provider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredKeyedService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>IScheduler<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>tenant<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>The unkeyed <code>IScheduler</code> is <strong>the default scheduler</strong> — the one registered by <code>AddQuartz(q =&gt; …)</code> with no name. In a container holding only named schedulers there is no unkeyed registration at all, and <code>GetRequiredService&lt;IScheduler&gt;()</code> throws. Resolve by key, or register a default scheduler as well.</p></div><p>Trying to give a named scheduler and the default scheduler the same name is caught at registration: <code>AddQuartz(o =&gt; o.InstanceName = &quot;acme&quot;)</code> beside <code>AddQuartz(&quot;acme&quot;, …)</code> fails with a message naming both calls, rather than as a duplicate-name <code>ArgumentException</code> from somewhere inside host start.</p><div class="hint-container warning"><p class="hint-container-title">A scheduler name is compared two different ways</p><p>Not one, and knowing which is which saves an afternoon:</p><ul><li><strong>Case-insensitive</strong>: the duplicate-name check, and every <code>ISchedulerRepository</code> lookup. So <code>AddQuartz(&quot;Acme&quot;, …)</code> beside <code>AddQuartz(&quot;acme&quot;, …)</code> is refused as one name, <code>repository.Lookup(&quot;acme&quot;)</code> finds the scheduler registered as <code>Acme</code>, and so does the HTTP API route <code>…/schedulers/acme/…</code>, which resolves through that repository.</li><li><strong>Ordinal</strong>: keyed resolution out of the container, and named options. So for a scheduler registered as <code>Acme</code>, <code>GetRequiredKeyedService&lt;IScheduler&gt;(&quot;acme&quot;)</code> throws — the container compares service keys by equality, and string equality is ordinal — and <code>Configure&lt;QuartzOptions&gt;(&quot;acme&quot;, …)</code> configures nothing, because the options framework matches instance names ordinally too.</li></ul><p>Neither comparison is wrong for what it does; they are simply different, and only the first one is forgiving. Spell the name once, put it in a constant, and use that constant everywhere.</p></div><h3 id="listing-them" tabindex="-1"><a class="header-anchor" href="#listing-them"><span>Listing them</span></a></h3><p><code>ISchedulerFactory.GetAllSchedulers()</code> lists the schedulers something has already <em>created</em>. Under this model that is the wrong question: a tenant nobody has asked for yet is still a tenant, and building every one of them to find out what exists is exactly the cost you were avoiding.</p><p><code>ISchedulerRegistry</code> reads the registrations instead:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ISchedulerRegistry</span> registry <span class="token operator">=</span> provider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ISchedulerRegistry<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name">SchedulerRegistration</span> tenant <span class="token keyword">in</span> <span class="token keyword">await</span> registry<span class="token punctuation">.</span><span class="token function">QuerySchedulers</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span><span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">tenant<span class="token punctuation">.</span>Name</span><span class="token punctuation">}</span></span><span class="token string">: </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">tenant<span class="token punctuation">.</span>Status<span class="token punctuation">?.</span><span class="token function">ToString</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">??</span> <span class="token string">&quot;registered, not created&quot;</span></span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Status</code> is <code>null</code> when no scheduler exists under that name, and asking does not build one. A scheduler that has been <em>shut down</em> reads as <code>null</code> too rather than as <code>Shutdown</code>, because the repository drops a shut-down scheduler as soon as a read notices it — and a shut-down scheduler cannot be rebuilt in the same container anyway, so &quot;not yet&quot; and &quot;not any more&quot; are the same answer here: not a name you can get a working scheduler out of. A scheduler whose state cannot be read at all — a remote one from <code>AddQuartzHttpClient</code>, when the other process is unreachable — is reported as <code>SchedulerStatus.Unknown</code> rather than dropped from the listing or allowed to throw: an inventory of tenants is exactly the call that must not fail because one of them is down.</p><p><code>Origin</code> says where the scheduler came from: <code>Container</code> for one <code>AddQuartz</code> registered, <code>Runtime</code> for one that is in the repository without a registration behind it — a <code>QuartzSchedulerBuilder</code> scheduler bound by hand, or a remote scheduler from <code>AddQuartzHttpClient</code>. The default scheduler appears under its configured <code>InstanceName</code>.</p><p>Under <code>AddQuartzHostedService()</code> every registration is <em>built</em> while the host starts, so once the host is up the distinction matters less than it looks. It matters while the host is still starting, when you resolve schedulers yourself, when a start failed, and whenever you want an inventory rather than a list of live objects.</p><p>The dashboard and the HTTP API read the same registry, so a tenant nothing has built is listed by both. <code>GET {ApiPath}/schedulers</code> reports it with a <code>null</code> status and no instance id, and the dashboard&#39;s <strong>Schedulers</strong> page at <code>/quartz/schedulers</code> gives it a row saying <strong>not created</strong> — beside, for every tenant that does exist, what its job store and thread pool are, when it started, how many jobs it has executed and how many nodes it has. The header&#39;s scheduler picker offers it too, greyed out.</p><div class="hint-container warning"><p class="hint-container-title">A tenant&#39;s own routes still resolve through the repository</p><p>The listing is the one read that goes through the registry. Everything addressed <em>at</em> a scheduler — <code>GET {ApiPath}/schedulers/acme</code>, its jobs, its triggers — resolves through <code>ISchedulerRepository</code>, which holds the schedulers something has already built, so those routes answer <code>404</code> for a tenant nothing has created. Not because the name is unknown: the listing is where you see that it is not. Under <code>AddQuartzHostedService()</code> that window closes as the host starts; outside it — a scheduler resolved lazily, or one whose start failed — it stays open.</p></div><h3 id="what-is-per-scheduler" tabindex="-1"><a class="header-anchor" href="#what-is-per-scheduler"><span>What is per scheduler</span></a></h3><p>Almost everything. Each named scheduler gets its own keyed registration of the job factory, the signaler, the thread pool, the job store, the driver delegate, the object serializer, the instance-id generator, the scheduler itself and its factory — plus its own listeners, plugins, calendars, jobs and triggers.</p><div class="hint-container warning"><p class="hint-container-title">Listeners and plugins are not symmetrical about the unkeyed registration</p><p>A listener and a plugin are both &quot;registered per scheduler&quot;, and they treat a plain <code>IServiceCollection</code> registration in opposite ways.</p><ul><li><strong>An unkeyed <code>ISchedulerListener</code>, <code>IJobListener</code> or <code>ITriggerListener</code> service reaches every scheduler in the container.</strong> A scheduler unions the unkeyed listener services with the ones keyed to it, so <code>services.AddSingleton&lt;IJobListener, AuditListener&gt;()</code> is a container-wide listener — not the default scheduler&#39;s. Keyed registrations belong to the scheduler they name.</li><li><strong>An unkeyed <code>ISchedulerPlugin</code> service reaches only the default scheduler.</strong> A named scheduler reads the plugins keyed to it and nothing else, and <a href="#plugins-named-by-properties">the properties probe</a> has no unkeyed fallback either.</li></ul><p>The asymmetry is the difference between a listener, which is told which scheduler it is hearing from on every callback, and a plugin, which is <em>bound</em> to one when it is initialized. So several schedulers cannot share a plugin instance; each needs its own, and <a href="#giving-every-scheduler-the-same-thing"><code>ConfigureAllQuartzSchedulers</code></a> is how to ask for that once.</p></div><p>Options are <strong>named options</strong> whose name is the scheduler&#39;s name, and the container rewrites <code>IOptions&lt;T&gt;</code> for a scheduler&#39;s own components so that <code>.Value</code> means <em>that</em> scheduler&#39;s settings. Quartz&#39;s own option types — <code>QuartzSchedulerOptions</code>, <code>ThreadPoolOptions</code>, <code>InMemoryJobStoreOptions</code>, <code>AdoJobStoreOptions</code>, <code>ClusteringOptions</code> and <code>QuartzOptions</code> — are declared that way once, in the container; every other options type opts in by being <em>declared</em>, which is what <code>ConfigureOptions&lt;TOptions&gt;()</code> does. That is also how <code>JobFactoryOptions</code> becomes per-scheduler: <code>ConfigureJobScope(…)</code> is a <code>ConfigureOptions&lt;JobFactoryOptions&gt;</code> call, so the declaration arrives with the hook rather than being built in. <code>AddPlugin&lt;T, TOptions&gt;()</code> does the same for a plugin&#39;s own options type.</p><p>A clock is per scheduler too, when you set one:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">UseTimeProvider</span><span class="token punctuation">(</span>acmeClock<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>A scheduler with no clock of its own inherits the container&#39;s, which is what lets an application-wide <code>TimeProvider</code> reach all of them without being told about each.</p><h3 id="job-types" tabindex="-1"><a class="header-anchor" href="#job-types"><span>Job types</span></a></h3><p><code>AddJob&lt;T&gt;</code> registers the job type with the container so that a dependency it cannot be given is reported when the container is validated. That registration is unkeyed and <code>TryAdd</code>, which is right for one scheduler and not enough for several: the first registration would be what every scheduler got.</p><p><code>AddJobType</code> gives one scheduler its own:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobType</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ReportJob<span class="token punctuation">,</span> AcmeReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// a different implementation</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobType</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>AuditJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>ServiceLifetime<span class="token punctuation">.</span>Singleton<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// a different lifetime</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobType</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ExportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>sp <span class="token operator">=&gt;</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ExportJob</span><span class="token punctuation">(</span>sp<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredKeyedService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>IExportSink<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;report&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The job factory looks for this scheduler&#39;s registration first and falls back to the container&#39;s, so a scheduler given nothing of its own resolves what the container holds and the default scheduler — which has no service key — resolves in one lookup as it always has.</p><p>Two things worth knowing before reaching for it:</p><ul><li>The lifetime the job factory is built around is <strong>scoped</strong>: a scope is opened per fire, the job is resolved from it, and the scope is disposed when the job returns. <code>ServiceLifetime.Singleton</code> means one instance serves every fire of that job on that scheduler, so it must be thread-safe and must not capture scoped dependencies.</li><li>A job type per tenant is usually the wrong shape at more than a handful of tenants. One job type that reads its tenant from the firing and resolves what it needs — by key, if you like — inside <code>Execute</code> scales where a registration per tenant does not.</li></ul><h3 id="plugins-named-by-properties" tabindex="-1"><a class="header-anchor" href="#plugins-named-by-properties"><span>Plugins named by properties</span></a></h3><p>A <code>quartz.plugin.&lt;name&gt;.*</code> entry is read from the property bag of the scheduler it was configured on, so two tenants each configuring a scheduling-data plugin get two instances with their own files:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">NameValueCollection</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.plugin.json.type&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token keyword">typeof</span><span class="token punctuation">(</span><span class="token type-expression class-name">JsonSchedulingDataProcessorPlugin</span><span class="token punctuation">)</span><span class="token punctuation">.</span>AssemblyQualifiedName<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;quartz.plugin.json.fileNames&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;acme-jobs.json&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Before the instance is built, the container is asked whether that type is registered as a service — and that question is asked <strong>under this scheduler&#39;s key</strong>. So a named scheduler gets the registration made for it, an unkeyed registration belongs to the default scheduler, and a scheduler with no registration of its own gets a fresh instance built from its own properties. There is deliberately no fallback from one scheduler&#39;s key to the unkeyed registration: a plugin is told which scheduler it extends when it is initialized, so handing one instance to two schedulers means the second initialization overwrites the first.</p><p>To give a named scheduler a plugin instance you built yourself, register it under that scheduler — <code>q.AddPlugin&lt;T&gt;(provider =&gt; …)</code> — rather than unkeyed on <code>IServiceCollection</code>.</p><h3 id="giving-every-scheduler-the-same-thing" tabindex="-1"><a class="header-anchor" href="#giving-every-scheduler-the-same-thing"><span>Giving every scheduler the same thing</span></a></h3><p>Writing the same three lines inside every <code>AddQuartz(tenant, …)</code> is what a <code>foreach</code> over the tenants saves you, right up until the tenants come from configuration and the loop is not yours to write. <code>ConfigureAllQuartzSchedulers</code> applies one configuration callback to every scheduler in the container:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span>acme<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartzSchedulers</span><span class="token punctuation">(</span>builder<span class="token punctuation">.</span>Configuration<span class="token punctuation">.</span><span class="token function">GetSection</span><span class="token punctuation">(</span><span class="token string">&quot;Quartz&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Every scheduler above, and every scheduler registered after this line</span></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">ConfigureAllQuartzSchedulers</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddPlugin</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>TenantAuditPlugin<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobListener</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>AuditListener<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Four things it promises:</p><ul><li><strong>Order does not matter.</strong> It runs after each scheduler&#39;s own configuration callback either way: a scheduler registered before this call is configured here, one registered after it is configured by its own <code>AddQuartz</code>, and both get it <em>after</em> their own callback. So a scheduler&#39;s own configuration is what a shared callback refines whichever order the two calls were written in — which is the point, since a package that adds something to every scheduler cannot know when the application registers its schedulers.</li><li><strong>The usual precedence follows from that.</strong> Registration is first-wins, so a job store or thread pool a tenant chose for itself is not replaced by one chosen here; options are last-wins, so a value set here overrides the same option set on one tenant, exactly as <code>ConfigureAll&lt;TOptions&gt;</code> overrides an earlier named <code>Configure</code>.</li><li><strong>Every scheduler gets its own instance of whatever the callback adds.</strong> The delegate is handed a builder <em>per scheduler</em>, so what it registers lands under that scheduler&#39;s key: a plugin added this way to three schedulers is three plugin instances, each initialized with the name of the scheduler it extends — which is exactly what a plugin registered unkeyed cannot be.</li><li><strong>It reaches <code>AddQuartz()</code>, <code>AddQuartz(name, …)</code> and <code>AddQuartzSchedulers(…)</code> alike</strong>, because all three register a builder. Remote schedulers from <code>AddQuartzHttpClient</code> are skipped: they live in another process, so there is no builder here to configure and nothing this callback adds could reach them. Calling it when no scheduler is registered at all is not an error — the delegate applies to nothing.</li></ul>`,52),e(`p`,null,[l[4]||=r(`It is the options pattern's `,-1),l[5]||=e(`code`,null,`ConfigureAll`,-1),l[6]||=r(` for schedulers, and it is how `,-1),l[7]||=e(`code`,null,`AddQuartzDashboard`,-1),l[8]||=r(` gives every scheduler the dashboard's own plugins rather than only the default one — which is what stops a named scheduler's live view and history pages from being permanently empty. The `,-1),c(h,{to:`/documentation/quartz-4.x/migration-guide.html#every-scheduler-in-the-container-can-be-configured-at-once`},{default:i(()=>[...l[3]||=[r(`migration guide`,-1)]]),_:1}),l[9]||=r(` states the same rules for a reader arriving from 3.x.`,-1)]),l[58]||=t(`<h3 id="what-is-not" tabindex="-1"><a class="header-anchor" href="#what-is-not"><span>What is not</span></a></h3><p>A handful of things are container-wide, shared by every scheduler in the process:</p><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>ITypeLoader</code></td><td>type loading is a container-wide concern; <code>UseTypeLoader&lt;T&gt;()</code> <strong>replaces</strong> it for everyone, and the renames <code>UseTypeLoader(configure)</code> declares are in force for everyone</td></tr><tr><td><code>ISchedulerRepository</code></td><td>one per container — that is what makes <code>GetAllSchedulers</code> and the dashboard see all of them</td></tr><tr><td><code>ISchedulerRegistry</code></td><td>one per container — it answers for every registration in it, which is what makes it an inventory rather than a scheduler&#39;s own view</td></tr><tr><td><code>IJobExecutionContextAccessor</code></td><td>one per container, and the firing it reports is a property of the asynchronous flow rather than of a scheduler — a flow is inside at most one firing, whichever scheduler started it</td></tr><tr><td><code>SystemTextJsonSerializerRegistry</code></td><td>one per container by default — the HTTP API and the HTTP client serialize triggers without knowing which scheduler they came from. A named scheduler <em>can</em> be given its own, see below</td></tr><tr><td><code>Meters</code></td><td>built from the container&#39;s <code>IMeterFactory</code></td></tr><tr><td><code>DataSourceOptions</code></td><td>named after the <strong>data source</strong>, not the scheduler, so several schedulers can read through the same one</td></tr><tr><td><code>QuartzHttpApiOptions</code>, <code>QuartzDashboardOptions</code></td><td>one of each per process: they describe the surfaces, and every scheduler is reached through them. <em>Which</em> schedulers a caller reaches is per scheduler — see <a href="#authorizing-a-tenant-on-its-own-scheduler">Authorizing a tenant on its own scheduler</a> — but what they may do once there is not</td></tr></tbody></table><p>Logging is one per container rather than one per scheduler: every scheduler&#39;s parts are injected the container&#39;s <code>ILoggerFactory</code>, and a line says which tenant wrote it through the logging scope the scheduling loop opens — <code>quartz.scheduler.name</code> and <code>quartz.scheduler.id</code>, the same attribute names the traces and the measurements use. Filter or enrich on those rather than looking for a logger per tenant.</p><p>And one thing that is not a container service at all: <strong><code>LogProvider</code></strong> is process-wide static state. <code>SetLogProvider(loggerFactory)</code> sets it for everything in the process, deliberately. It no longer has anything to do with whether a scheduler logs; what it reaches is the types no container builds — a listener or trigger you constructed, the static helpers, the jobs in <code>Quartz.Jobs</code>.</p>`,5),e(`p`,null,[l[11]||=r(`The serializer registry is the one row in that table with a way out. A named scheduler resolves its registry by key and falls back to the container's, so `,-1),l[12]||=e(`code`,null,`services.AddKeyedSingleton(schedulerName, registry)`,-1),l[13]||=r(` — or the per-store `,-1),l[14]||=e(`code`,null,`UseSystemTextJsonSerializer(json => …)`,-1),l[15]||=r(` callback, which is the same thing — gives one tenant its own custom trigger and calendar serializers. What that changes is what `,-1),l[16]||=e(`em`,null,`that scheduler's job store`,-1),l[17]||=r(` persists and reads. Everything that serializes without a scheduler in hand — the HTTP API's responses, the dashboard, `,-1),l[18]||=e(`code`,null,`Quartz.HttpClient`,-1),l[19]||=r(` — still reads the container's registry, so a custom type those must render has to be registered there as well. See `,-1),c(h,{to:`/documentation/quartz-4.x/packages/system-text-json.html#making-custom-serializers-visible-outside-the-job-store`},{default:i(()=>[...l[10]||=[r(`System.Text.Json serialization`,-1)]]),_:1}),l[20]||=r(`.`,-1)]),l[59]||=t(`<h3 id="health-checks-per-tenant" tabindex="-1"><a class="header-anchor" href="#health-checks-per-tenant"><span>Health checks per tenant</span></a></h3><p><code>AddQuartzHealthChecks</code> called on a <em>scheduler&#39;s</em> builder checks that scheduler, and defaults its name to <code>quartz-scheduler-&lt;scheduler name&gt;</code> so several can be registered side by side:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">AddQuartzHealthChecks</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>Tags<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span><span class="token string">&quot;tenant:acme&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Called on <code>IServiceCollection</code> instead, it checks the default scheduler only.</p><h3 id="authorizing-a-tenant-on-its-own-scheduler" tabindex="-1"><a class="header-anchor" href="#authorizing-a-tenant-on-its-own-scheduler"><span>Authorizing a tenant on its own scheduler</span></a></h3><p><code>QuartzHttpApiOptions.SchedulerAuthorizationPolicy</code> and <code>QuartzDashboardOptions.SchedulerAuthorizationPolicy</code> each name a policy that is evaluated once per request against the scheduler that request is for. Quartz supplies the resource — a <code>SchedulerResource</code> carrying the scheduler&#39;s name — and the application writes the handler. This is ASP.NET Core&#39;s own resource-based authorization rather than anything Quartz invented, so there is no callback type to implement and no claim name Quartz decides for you:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// What &quot;may act on this scheduler&quot; means is the application&#39;s to decide, so the requirement itself</span></span>
<span class="line"><span class="token comment">// says nothing and the handler says everything.</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">SchedulerOwnerRequirement</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IAuthorizationRequirement</span></span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">SchedulerOwnerHandler</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">AuthorizationHandler<span class="token punctuation">&lt;</span>SchedulerOwnerRequirement<span class="token punctuation">,</span> SchedulerResource<span class="token punctuation">&gt;</span></span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">protected</span> <span class="token keyword">override</span> <span class="token return-type class-name">Task</span> <span class="token function">HandleRequirementAsync</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token class-name">AuthorizationHandlerContext</span> context<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">SchedulerOwnerRequirement</span> requirement<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">SchedulerResource</span> resource<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">string</span><span class="token punctuation">?</span></span> tenant <span class="token operator">=</span> context<span class="token punctuation">.</span>User<span class="token punctuation">.</span><span class="token function">FindFirst</span><span class="token punctuation">(</span><span class="token string">&quot;tenant&quot;</span><span class="token punctuation">)</span><span class="token punctuation">?.</span>Value<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// Scheduler names are compared ignoring case everywhere else in Quartz, so compare them that</span></span>
<span class="line">        <span class="token comment">// way here too - otherwise &quot;Acme&quot; and &quot;acme&quot; are the same scheduler and different tenants.</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">string</span><span class="token punctuation">.</span><span class="token function">Equals</span><span class="token punctuation">(</span>tenant<span class="token punctuation">,</span> resource<span class="token punctuation">.</span>SchedulerName<span class="token punctuation">,</span> StringComparison<span class="token punctuation">.</span>OrdinalIgnoreCase<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            context<span class="token punctuation">.</span><span class="token function">Succeed</span><span class="token punctuation">(</span>requirement<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">return</span> Task<span class="token punctuation">.</span>CompletedTask<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Register the policy, the handler, and the two options — one handler answers for both surfaces:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddAuthorizationBuilder</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">AddPolicy</span><span class="token punctuation">(</span><span class="token string">&quot;SchedulerOwner&quot;</span><span class="token punctuation">,</span> policy <span class="token operator">=&gt;</span> policy<span class="token punctuation">.</span><span class="token function">AddRequirements</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">SchedulerOwnerRequirement</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddSingleton</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>IAuthorizationHandler<span class="token punctuation">,</span> SchedulerOwnerHandler<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// One policy, one handler, both surfaces: the API answers 403 for a scheduler the caller fails</span></span>
<span class="line"><span class="token comment">// for, and the dashboard offers them only the schedulers they pass for.</span></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartzHttpApi</span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span> options<span class="token punctuation">.</span>SchedulerAuthorizationPolicy <span class="token operator">=</span> <span class="token string">&quot;SchedulerOwner&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartzDashboard</span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span> options<span class="token punctuation">.</span>SchedulerAuthorizationPolicy <span class="token operator">=</span> <span class="token string">&quot;SchedulerOwner&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>On the HTTP API</strong>, every route that carries <code>{schedulerName}</code> is checked before the scheduler is looked up, so a caller who fails is answered <code>403</code> with problem details and cannot tell &quot;not yours&quot; from &quot;no such scheduler&quot;: a <code>404</code> only ever answers a name the caller was allowed to ask about. <code>GET {ApiPath}/schedulers</code> names no scheduler, so it filters itself — a tenant is told about its own schedulers and learns nothing about the others, registrations included. The check is authorization and never authentication: an anonymous caller gets whatever the policy says, which is a <code>403</code> when it refuses, so keep <code>RequireAuthorization()</code> on the mapped group if anonymous callers should be challenged with a <code>401</code> first.</p>`,10),e(`p`,null,[l[22]||=e(`strong`,null,`On the dashboard`,-1),l[23]||=r(`, the scheduler picker and the Schedulers page offer only the schedulers the visitor passes for; a page opened on one they do not renders a "not authorized" frame and reads nothing about that scheduler; and the live-events hub refuses to subscribe a connection to its group. It composes with what was already there: `,-1),l[24]||=e(`code`,null,`AuthorizationPolicy`,-1),l[25]||=r(` decides who reaches the dashboard at all, this decides which schedulers they see once they are in, and `,-1),l[26]||=e(`code`,null,`ReadOnly`,-1),l[27]||=r(` still decides what anyone may change. That frame is the dashboard's own layout, so read `,-1),c(h,{to:`/documentation/quartz-4.x/packages/dashboard.html#one-scheduler-at-a-time`},{default:i(()=>[...l[21]||=[r(`Standalone hosting is where this applies today`,-1)]]),_:1}),l[28]||=r(` before relying on it in an application that hosts the components under a layout of its own.`,-1)]),l[60]||=t(`<p>Null — the default — is the behaviour every earlier release had, so nothing changes for an application that does not set it. Setting it in a container with no authorization services fails at startup rather than quietly enforcing nothing; a policy name no <code>IAuthorizationPolicyProvider</code> knows fails the way it does everywhere else in ASP.NET Core, at the first request that names it.</p><h2 id="group-per-tenant" tabindex="-1"><a class="header-anchor" href="#group-per-tenant"><span>Group per tenant</span></a></h2><p>One scheduler; the tenant is the group half of every key.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">JobKey</span> job <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token string">&quot;nightly-report&quot;</span><span class="token punctuation">,</span> tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">TriggerKey</span> trigger <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">,</span> tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Everything that takes a matcher then becomes tenant-scoped:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// everything this tenant has scheduled</span></span>
<span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span></span> theirs <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggers</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerQuery</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Group <span class="token operator">=</span> GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Take <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">,</span></span>
<span class="line">    IncludeTotalCount <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// suspend a tenant</span></span>
<span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span><span class="token keyword">string</span><span class="token punctuation">&gt;</span></span> paused <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">PauseTriggerGroups</span><span class="token punctuation">(</span>GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// is a tenant suspended?</span></span>
<span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerGroup<span class="token punctuation">&gt;</span></span> <span class="token keyword">group</span> <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggerGroups</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerGroupQuery</span> <span class="token punctuation">{</span> Name <span class="token operator">=</span> NameMatcher<span class="token punctuation">.</span><span class="token function">NameEquals</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">,</span> Take <span class="token operator">=</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">bool</span></span> suspended <span class="token operator">=</span> <span class="token keyword">group</span><span class="token punctuation">.</span>Items <span class="token keyword">is</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> Paused<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Pause state is real and queryable for both trigger groups and job groups — the ADO store persists a paused job group in <code>QRTZ_PAUSED_JOB_GRPS</code>, so <code>QueryJobGroups(new JobGroupQuery { Name = tenantId, Take = 1 })</code> answers for a tenant partitioned by job group just as well. Still suspend by <strong>trigger</strong> group where the suspension has to reach work scheduled after it: a paused trigger group starts a later trigger paused on either store, where a paused job group does so only in the in-memory one.</p><p>Listeners take matchers too, so a per-tenant listener is one registration:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobListener</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>AuditListener<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>Matchers<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Group</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>JobKey<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>StringOperator<span class="token punctuation">.</span>Equality<span class="token punctuation">,</span> tenantId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="what-the-group-model-does-not-partition" tabindex="-1"><a class="header-anchor" href="#what-the-group-model-does-not-partition"><span>What the group model does not partition</span></a></h3><p>The matcher reaches everything that takes one — and the two operator surfaces do not take one. <strong>Quartz authorizes a scheduler, never a group</strong>: the resource a policy is evaluated against is a <code>SchedulerResource</code> carrying a scheduler&#39;s name, so under this model every tenant&#39;s jobs, triggers and history are visible to anyone who reaches the dashboard or the HTTP API at all. There is no group-shaped equivalent of <a href="#authorizing-a-tenant-on-its-own-scheduler"><code>SchedulerAuthorizationPolicy</code></a>, and a group matcher in a query string is a filter rather than a boundary — a caller can simply pass a different one.</p><p>If tenants must not see each other on those surfaces, that is the argument for giving them schedulers, or for putting your own API in front of Quartz&#39;s and never exposing Quartz&#39;s to them. It is not an argument against the group model for everything else: the isolation the group model <em>does</em> give — scheduling, pausing, quotas, listeners — is real, and most deployments never expose the dashboard to tenants in the first place.</p><h3 id="per-tenant-concurrency-quotas" tabindex="-1"><a class="header-anchor" href="#per-tenant-concurrency-quotas"><span>Per-tenant concurrency quotas</span></a></h3><p>Execution groups cap how many threads a category of work may use. When the schedule already partitions work by trigger group — a tenant per group — the trigger group can stand in for the execution group, so a quota is one line per tenant and no change to any trigger:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span>limits <span class="token operator">=&gt;</span> limits</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">UseTriggerGroupWhenUnset</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> <span class="token number">8</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span>          <span class="token comment">// a big tenant</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;initech&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// everyone else gets one thread each</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ExecutionLimitScope.Cluster</code> is what makes these quotas rather than capacity settings: the number is what every node sharing the job store may run <strong>between them</strong>, counted from the reservations the store itself is holding. Leave the scope off and each limit is per node instead, which on a three-node cluster means <code>ForGroup(&quot;acme&quot;, 8)</code> allows 24 concurrent Acme jobs. Both scopes are legitimate — node-scoped for &quot;this machine can stand eight&quot;, cluster-scoped for &quot;this tenant is entitled to eight&quot; — and one set of limits can hold both.</p><p><code>UseTriggerGroupWhenUnset()</code> changes nothing about the data — the trigger still carries no execution group, and the store still persists none. It changes only how a limit is looked up. Three consequences:</p><ul><li>An explicit <code>ExecutionGroup</code> on a trigger always wins.</li><li><code>ForDefaultGroup</code> stops catching anything, because with this on nothing is ungrouped. Unlisted tenants fall under <code>ForOtherGroups</code>.</li><li>Each unlisted group gets <strong>its own</strong> allowance from <code>ForOtherGroups</code>, not a shared one. Three unlisted tenants under <code>ForOtherGroups(1)</code> can run three jobs, one each.</li></ul><p><code>Unlimited(group)</code> is not the same as leaving a group out: an unlisted group falls back to <code>ForOtherGroups</code>, an explicitly unlimited one does not.</p><p>Limits can also be changed at runtime with <code>SetExecutionLimits</code> / <code>GetExecutionLimits</code> — they take effect on the next acquisition cycle, and <code>null</code> clears them. The call is per node whichever scope the limits use: it replaces what <em>this</em> scheduler enforces, so a cluster-scoped quota you mean every node to honour has to be set on every node, or configured rather than set.</p>`,20),e(`div`,d,[l[36]||=t(`<p class="hint-container-title">What a cluster-scoped quota does and does not promise</p><p>The ceiling holds <strong>within one acquisition round</strong>, and by default acquisition takes no cluster lock, so a brief overshoot is possible while several nodes acquire at once — at most <code>limit + (nodes − 1)</code>, until the losers notice. The lock-free path exists only when a round acquires a single trigger: the ADO store takes the <code>TRIGGER_ACCESS</code> lock whenever it is asked for more than one, so a node acquiring without the lock can add at most one over the ceiling. <code>AcquireTriggersWithinLock = true</code> makes it exact and serializes acquisition cluster-wide.</p><p>It <strong>fails closed</strong>: the quota ledger and the work queue are the same database, so a node that cannot reach the store fires nothing at all rather than firing unmetered. Plan for a database outage stopping work, not for it removing the ceiling.</p>`,3),e(`p`,null,[l[30]||=r(`A group held at its ceiling for longer than `,-1),l[31]||=e(`code`,null,`MisfireThreshold`,-1),l[32]||=r(` (one minute by default) feeds its backlog into misfire handling. Pair a tight quota with `,-1),l[33]||=e(`code`,null,`MisfireInstruction.IgnoreMisfirePolicy`,-1),l[34]||=r(` or a larger threshold. See `,-1),c(h,{to:`/documentation/quartz-4.x/tutorial/execution-groups.html#clustering-considerations`},{default:i(()=>[...l[29]||=[r(`Execution Groups`,-1)]]),_:1}),l[35]||=r(` for the full statement.`,-1)])]),l[61]||=t(`<h2 id="shared-database" tabindex="-1"><a class="header-anchor" href="#shared-database"><span>Shared database</span></a></h2><p>Every Quartz table has <code>SCHED_NAME</code> as the first column of its primary key, and every statement filters on it. Two schedulers with different names therefore share tables without seeing each other&#39;s rows, and that is a property of the schema rather than of the code paths — there is no query that forgets.</p><p>Table prefix is the other axis. <code>AdoJobStoreOptions.TablePrefix</code> (default <code>QRTZ_</code>) is a per-scheduler option, so two tenants can have entirely separate table <em>sets</em> in one database:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span>sharedConnectionString<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    s<span class="token punctuation">.</span><span class="token function">ConfigureStore</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>TablePrefix <span class="token operator">=</span> <span class="token string">&quot;ACME_QRTZ_&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Four rules:</p><ul><li><strong>Different scheduler name is enough.</strong> Prefixes are for keeping tenants in separate <em>tables</em>, which is a backup-and-restore or a permissions decision, not an isolation one.</li><li><strong>The prefix has to match the DDL.</strong> Nothing derives one from the other; you run the DDL with the prefix substituted.</li><li><strong>A prefix pointing at tables that do not exist is caught at startup.</strong><code>SchemaProvisioning.Validate</code> is the default, and a missing or mis-prefixed table is reported once, by name, with a message telling you to run the schema scripts — rather than surfacing as the first failing operation an hour later.</li><li><strong>A prefix pointing at the <em>wrong</em> tables is reported too, as a warning.</strong> Schema validation cannot catch that one: the tables exist, they are simply somebody else&#39;s, and the scheduler starts, reports healthy and never sees its own data. So creating a scheduler records its database and its table prefix, and a scheduler that shares a database with one already created but disagrees about the prefix produces a <code>Warning</code> naming both schedulers and both prefixes. Prefixes are compared <strong>ignoring case</strong>, because every database Quartz supports folds an unquoted identifier to one case — <code>qrtz_</code> and <code>QRTZ_</code> are one table set, and two tenants told apart only by the casing of their prefix are one tenant.</li></ul><div class="hint-container tip"><p class="hint-container-title">Why that one is a warning and not an error</p><p>Separate table sets in one database are legal, and the arrangement above is exactly how you ask for them. Nothing Quartz can see tells a deliberate <code>ACME_QRTZ_</code> apart from a mistyped <code>QRTZ2_</code>, and an error that fires on a legitimate arrangement is worse than the silence it replaces. If the two prefixes are meant to differ, the warning is expected and can be filtered out on the <code>Quartz.Configuration.SharedDatabaseValidator</code> category.</p><p>It also only sees what one container can see. Two processes — or two containers in one process — sharing a database are invisible to each other, and so is a database reached through a provider that reports neither a connection string nor a <code>DbDataSource</code>. Being wrong in that direction is deliberate: a check that stays quiet when it cannot tell costs you nothing.</p></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Two schedulers sharing a database with the <strong>same</strong> <code>SCHED_NAME</code> are, by construction, indistinguishable from two nodes of one cluster — because that is exactly what they look like to the schema. Schema validation will not catch it, and they will steal each other&#39;s triggers. The duplicate-name check protects you only within one container; across processes, the name is a contract you keep.</p></div><h2 id="per-tenant-services-inside-a-job" tabindex="-1"><a class="header-anchor" href="#per-tenant-services-inside-a-job"><span>Per-tenant services inside a job</span></a></h2><p>A job needs to reach <em>its</em> tenant&#39;s database, its tenant&#39;s configuration, its tenant&#39;s feature flags. The scheduler builds jobs from a DI scope, and <code>ConfigureJobScope</code> prepares that scope before the job and everything it injects are constructed:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">class</span> <span class="token class-name">TenantContext</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">readonly</span> <span class="token class-name">AsyncLocal<span class="token punctuation">&lt;</span><span class="token keyword">string</span><span class="token punctuation">?</span><span class="token punctuation">&gt;</span></span> current <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token return-type class-name"><span class="token keyword">string</span><span class="token punctuation">?</span></span> Current</span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">get</span> <span class="token operator">=&gt;</span> current<span class="token punctuation">.</span>Value<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">internal</span> <span class="token keyword">set</span> <span class="token operator">=&gt;</span> current<span class="token punctuation">.</span>Value <span class="token operator">=</span> <span class="token keyword">value</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token function">ConfigureJobScope</span><span class="token punctuation">(</span><span class="token punctuation">(</span>scope<span class="token punctuation">,</span> bundle<span class="token punctuation">,</span> scheduler<span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    TenantContext<span class="token punctuation">.</span>Current <span class="token operator">=</span> bundle<span class="token punctuation">.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Two things make this work, and both are deliberate:</p><ul><li><strong>The hook is synchronous.</strong> An asynchronous hook would be awaited, and the <code>ExecutionContext</code> restored on the way back would discard exactly the <code>AsyncLocal&lt;T&gt;</code> values it exists to set.</li><li><strong>The job is created on the execution path</strong>, not during initialization, so values set here flow into <code>Execute</code>.</li></ul><p>Callbacks combine rather than replace, and run in the order they were added.</p><p>The <code>TriggerFiredBundle</code> gives you the whole firing to derive the tenant from — <code>Trigger.Key.Group</code>, <code>JobDetail.Key.Group</code>, or a value out of <code>Trigger.JobDataMap</code> — plus the <code>IScheduler</code> that fired it, which is the tenant itself under the scheduler-per-tenant model.</p><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>The context does not exist yet when the hook runs — it takes the job instance, and the job has not been built. So the two patterns <em>for seeding construction</em> are the <code>AsyncLocal</code> above, and resolving a scoped holder object from <code>scope.ServiceProvider</code> and populating it. The second is easier to test and does not depend on execution context flow. For everything that reads the tenant when it is <em>used</em> rather than when it is constructed, <code>IJobExecutionContextAccessor</code> below is neither.</p></div><h3 id="which-scheduler-s-parts-a-job-is-built-from" tabindex="-1"><a class="header-anchor" href="#which-scheduler-s-parts-a-job-is-built-from"><span>Which scheduler&#39;s parts a job is built from</span></a></h3><p>A <strong>registered</strong> job is built by the <em>container</em>, and the container resolves constructor parameters <strong>unkeyed</strong> — it knows nothing about which scheduler is firing the job. A job on scheduler <code>acme</code> taking <code>IScheduler</code>, <code>ISchedulerFactory</code>, <code>IJobStore</code>, <code>IThreadPool</code> or <code>IOptions&lt;QuartzSchedulerOptions&gt;</code> would therefore be handed the <em>default</em> scheduler&#39;s, and in a container holding only named schedulers there would be no unkeyed registration to hand it at all.</p><p>So <strong>a registered job may not take a scheduler&#39;s parts by constructor, and startup says so.</strong><code>AddJob&lt;T&gt;</code>, <code>AddJob(type, …)</code>, <code>ScheduleJob&lt;T&gt;</code> and <code>AddJobType&lt;T&gt;</code> each record the job type against the scheduler they were called on, and validating that scheduler&#39;s options walks the public constructors of the type the container would build:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Job type ArchiveJob is registered on scheduler &#39;acme&#39;, and its constructor takes ISchedulerFactory</span>
<span class="line">schedulerFactory — a part that belongs to one scheduler. A registered job type is built by the</span>
<span class="line">container, which resolves constructor parameters without a scheduler&#39;s service key: what the job is</span>
<span class="line">handed is the unkeyed registration — the default scheduler&#39;s — whichever scheduler the job belongs to,</span>
<span class="line">and in a container holding only named schedulers there is no unkeyed registration to hand it. Read the</span>
<span class="line">scheduler running the job from IJobExecutionContext.Scheduler, take IJobExecutionContextAccessor for</span>
<span class="line">the firing it is part of, or register the job with AddJobType&lt;ArchiveJob&gt;(provider =&gt; ...) and resolve</span>
<span class="line">the part by key inside that factory.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Every public constructor is examined, not the one the container would pick: which one that is depends on what else the container holds — a constructor is only chosen when every parameter of it can be resolved — so a job whose clean constructor is picked today is picked differently the moment an unrelated registration appears. <code>TimeProvider</code> is the deliberate exception to the list: a scheduler given no clock of its own inherits the container&#39;s, and injecting a clock is what the rest of Quartz asks you to do.</p><p><strong>A job type the container does not hold is unaffected</strong>, and is not examined. It is activated by the job factory, through the scheduler-scoped provider, and its dependencies resolve to <em>its own</em> scheduler&#39;s parts — that is any job the container was never told about: one scheduled at runtime with <code>ScheduleJob(jobDetail, …)</code>, and one named only by an XML or JSON schedule.</p><p>There are three ways to write the job instead, and the first covers nearly every case. <strong>The scheduler running the fire is <code>IJobExecutionContext.Scheduler</code></strong>, which is that scheduler whichever path built the job:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">RotateTenantKeysJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// The scheduler running this fire, whichever tenant it belongs to. An injected</span></span>
<span class="line">        <span class="token comment">// ISchedulerFactory would have been the default scheduler&#39;s.</span></span>
<span class="line">        <span class="token class-name">IScheduler</span> mine <span class="token operator">=</span> context<span class="token punctuation">.</span>Scheduler<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">await</span> mine<span class="token punctuation">.</span><span class="token function">PauseTriggerGroups</span><span class="token punctuation">(</span></span>
<span class="line">            GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Code the context is not handed</strong> — a scoped service, a repository three calls below <code>Execute</code> — reads the firing from <a href="#reading-the-firing-from-anywhere-in-it"><code>IJobExecutionContextAccessor</code></a>.</p><p><strong>A job that genuinely has to be <em>constructed</em> with something of its scheduler&#39;s</strong> is registered with a factory of its own, which resolves that part by key. A registration built by a factory is not examined, because the factory is where the key goes:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">,</span> q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// A job the container builds may not take a scheduler&#39;s parts by constructor - startup</span></span>
<span class="line">    <span class="token comment">// refuses one that does. The job that genuinely has to be given them is built here instead,</span></span>
<span class="line">    <span class="token comment">// where the scheduler&#39;s key is known.</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobType</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ArchiveJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>provider <span class="token operator">=&gt;</span></span>
<span class="line">        <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ArchiveJob</span><span class="token punctuation">(</span>provider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredKeyedService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ISchedulerFactory<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token string">&quot;acme&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ArchiveJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;archive&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="reading-the-firing-from-anywhere-in-it" tabindex="-1"><a class="header-anchor" href="#reading-the-firing-from-anywhere-in-it"><span>Reading the firing from anywhere in it</span></a></h3><p>A great deal of code that wants the tenant is not the job and cannot be handed the context: a scoped service, a logging enricher, a repository three calls below <code>Execute</code>. <code>IJobExecutionContextAccessor</code> is the firing that code is part of:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TenantConnectionFactory</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token class-name">IJobExecutionContextAccessor</span> accessor<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">IReadOnlyDictionary<span class="token punctuation">&lt;</span><span class="token keyword">string</span><span class="token punctuation">,</span> <span class="token keyword">string</span><span class="token punctuation">&gt;</span></span> connectionStrings<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> ConnectionString <span class="token operator">=&gt;</span></span>
<span class="line">        connectionStrings<span class="token punctuation">[</span>accessor<span class="token punctuation">.</span>Current<span class="token punctuation">?.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group</span>
<span class="line">            <span class="token operator">??</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">InvalidOperationException</span><span class="token punctuation">(</span><span class="token string">&quot;no job is running on this flow&quot;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>It is registered by <code>AddQuartz</code> as a singleton, and it exposes the whole <code>IJobExecutionContext</code> rather than a tenant-shaped projection of it — Quartz has no tenant concept, so a narrower type here would be inventing one, and it would have to grow a member every time somebody needed one more fact the context already carries.</p><p>Four things about the window it is set for, all of them worth knowing before relying on it:</p><ul><li><strong>It is set from the moment the context exists</strong> — before the trigger and job listeners are notified — <strong>until the job has been returned to the job factory.</strong> Outside that it is <code>null</code>: on the scheduling thread, in application code that merely calls <code>ScheduleJob</code>, and in an <code>ISchedulerListener</code> reacting to a scheduling call rather than to a firing. Treat <code>null</code> as a real answer rather than an impossible one.</li><li><strong>It is never another firing&#39;s.</strong> The value travels with the <code>ExecutionContext</code>, so it belongs to the logical flow and not to the thread; a pooled thread picking up unrelated work inherits nothing.</li><li><strong>It survives <code>await</code> and <code>Task.Run</code>, and stops at the end of the firing.</strong> Work started inside the job and left running past <code>Execute</code> — a detached <code>Task.Run</code>, a continuation nobody awaits — reads <code>null</code> from the moment the execution ends, not the finished context. That is deliberate: by then the job&#39;s DI scope has been disposed and the context&#39;s cancellation handle is going. <code>ExecutionContext.SuppressFlow</code> hides it, as it hides every ambient value.</li><li><strong>There is no setter.</strong> An ambient context anyone can assign is one that can be left pointing at a firing that is over, which would be worse than having no accessor at all. Substitute the interface in a test instead.</li></ul><p>It does <strong>not</strong> replace <code>ConfigureJobScope</code>: the context does not exist while the job is being constructed, so anything that needs the tenant <em>at construction time</em> — a <code>DbContext</code> given a tenant connection string in its constructor — still gets it from the hook.</p><p>For anything more involved — resolving jobs from a tenant-owned container, say — implement <code>IJobFactory</code> and register it with <code>UseJobFactory&lt;T&gt;()</code>, or derive from <code>MicrosoftDependencyInjectionJobFactory</code> and override <code>protected virtual void ConfigureScope(...)</code>. An override that does not call <code>base</code> takes the delegate&#39;s place.</p><p>Per-fire options are a snapshot: read what the tenant&#39;s configuration says <em>inside</em> the hook or the job, not once at startup, if tenants can be reconfigured while the process runs.</p><h2 id="honest-limits" tabindex="-1"><a class="header-anchor" href="#honest-limits"><span>Honest limits</span></a></h2><p>Things multi-tenant deployments ask Quartz for and do not get:</p><p><strong>A cluster-wide concurrency ceiling is approximate, not exact, unless you pay for exactness.</strong><code>ExecutionLimitScope.Cluster</code> counts a group&#39;s in-flight work from <code>QRTZ_FIRED_TRIGGERS</code>, which is transactional and cluster-wide, but the default acquisition path takes no cluster lock — so the ceiling holds within one acquisition round and can transiently overshoot by up to <code>nodes − 1</code> while several nodes acquire at once. The overshoot is one trigger per node and no more, because the lock-free path is only taken when a round acquires a single trigger: asking for a batch takes the <code>TRIGGER_ACCESS</code> lock, which is the same lock <code>AcquireTriggersWithinLock = true</code> takes on every round. That setting removes the overshoot and serializes acquisition for every group, limited or not. There is no third setting that gives you both.</p><p><strong>There is no rate limiting.</strong> Execution limits cap <em>concurrency</em>, not throughput. &quot;This tenant may run 100 jobs an hour&quot; is not something Quartz can express; build it in the job, or in the thing the job calls. It is worth asking whether concurrency is what you actually meant: &quot;at most four of this tenant&#39;s jobs at once&quot; is usually the real requirement behind &quot;100 an hour&quot;, and it is the one Quartz can enforce honestly.</p><p><strong>Read-only is per process, and there is no per-operation policy.</strong> A tenant <em>can</em> be held to its own scheduler on both surfaces — see <a href="#authorizing-a-tenant-on-its-own-scheduler">Authorizing a tenant on its own scheduler</a> — but what a tenant may <em>do</em> to the scheduler it reaches is still one setting for the whole process: the dashboard&#39;s <code>ReadOnly</code> flag. &quot;acme may look, globex may act&quot; is not something either surface expresses, and neither is &quot;this tenant may pause but not delete&quot;. The resource-based shape leaves room for it — the policy is evaluated against a <code>SchedulerResource</code>, and an operation requirement could join it later without another option — but that is not built.</p><p><strong>Tenants cannot be onboarded at runtime <em>through the DI path</em>.</strong> Schedulers are registered against <code>IServiceCollection</code>, which is closed once the container is built, and the hosted service enumerates them once at start. (Enumerating what <em>is</em> registered no longer requires starting anything — <a href="#listing-them"><code>ISchedulerRegistry</code></a> — but adding to it does still require a new container.) Nor can a scheduler be restarted after <code>Shutdown()</code>: the container owns its parts&#39; lifetimes, and <code>GetScheduler()</code> throws rather than resurrecting a thread pool and a job store underneath a scheduler that can never run again. <code>Standby()</code> / <code>Start()</code> is the pause-and-resume pair.</p><p>That is a limit of the DI path, not of the library. <code>QuartzSchedulerBuilder</code> builds a scheduler from a container of its own, at any point in the process&#39;s life, and <code>ISchedulerRepository.Bind</code> makes the result visible to <code>GetAllSchedulers</code>, the dashboard and the HTTP API:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">StandaloneSchedulerFactory</span> tenantFactory <span class="token operator">=</span> QuartzSchedulerBuilder</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span> q</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ConfigureScheduler</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>InstanceName <span class="token operator">=</span> tenantId<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span>connectionStrings<span class="token punctuation">[</span>tenantId<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">IScheduler</span> tenant <span class="token operator">=</span> <span class="token keyword">await</span> tenantFactory<span class="token punctuation">.</span><span class="token function">GetScheduler</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> tenant<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tenantFactories<span class="token punctuation">[</span>tenantId<span class="token punctuation">]</span> <span class="token operator">=</span> tenantFactory<span class="token punctuation">;</span></span>
<span class="line">app<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ISchedulerRepository<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Bind</span><span class="token punctuation">(</span>tenant<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Keep the factory for as long as the tenant exists — <code>tenantFactories</code> above is a dictionary keyed by tenant id — because it owns the container and is the only handle that can shut the tenant down again. <code>BuildScheduler()</code> is the shorter spelling that drops it on the floor, which is fine for a scheduler that lives as long as the process and wrong for one that has to be offboarded.</p><p>What you take on by doing this: the returned <code>StandaloneSchedulerFactory</code> owns the container, so <em>you</em> start the scheduler and dispose the factory — the hosted service will not; the scheduler&#39;s jobs resolve from its own container rather than the application&#39;s unless you give it an <code>IJobFactory</code> that bridges; and health checks registered at startup do not cover it.</p><p><code>Bind</code> refuses a duplicate <strong>(name, instance id)</strong> pair, not a duplicate name: two schedulers of one name and different instance ids coexist by design, which is how proxies to several nodes of one cluster are held. In practice the common case still throws, because a scheduler that has not opted into clustering takes the default instance id <code>NON_CLUSTERED</code> — so two non-clustered tenants sharing a name collide on the pair. Give each tenant&#39;s scheduler a distinct <code>InstanceName</code> and the question does not arise.</p><p>Offboarding is disposing the factory, which shuts the tenant&#39;s scheduler down and then disposes its container. Unbind it too, so the application&#39;s repository stops listing it at once rather than at its next read:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">StandaloneSchedulerFactory</span> tenantFactory <span class="token operator">=</span> tenantFactories<span class="token punctuation">[</span>tenantId<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">tenantFactories<span class="token punctuation">.</span><span class="token function">Remove</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Disposal shuts the scheduler down without waiting for its jobs, so ask for the wait here.</span></span>
<span class="line"><span class="token class-name">IScheduler</span> tenant <span class="token operator">=</span> <span class="token keyword">await</span> tenantFactory<span class="token punctuation">.</span><span class="token function">GetScheduler</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> tenant<span class="token punctuation">.</span><span class="token function">Shutdown</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">waitForJobsToComplete</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">await</span> tenantFactory<span class="token punctuation">.</span><span class="token function">DisposeAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">app<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ISchedulerRepository<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Remove</span><span class="token punctuation">(</span>tenantId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Disposal does not wait for running jobs</p><p><code>StandaloneSchedulerFactory.DisposeAsync</code> shuts down with <code>waitForJobsToComplete: false</code>, so a tenant&#39;s jobs are cut short — which is the same default <code>IScheduler.Shutdown()</code> and <code>QuartzHostedServiceOptions</code> both carry, and two Quartz-owned shutdown paths that disagreed about it would be a trap. Waiting is a call you make first, as above: <code>await scheduler.Shutdown(waitForJobsToComplete: true)</code> leaves the factory with nothing left to shut down, so the two compose and the disposal only releases the container.</p></div><div class="hint-container warning"><p class="hint-container-title">Unbinding is not offboarding</p><p><code>Remove</code> makes a tenant invisible; only the disposal stops it. A recipe that unbinds without disposing takes the tenant out of <code>GetAllSchedulers</code>, off the dashboard and out of the HTTP API while it goes on firing its triggers for the rest of the process&#39;s life, with nothing left able to reach it. Disposing the factory shuts its scheduler down, which is what makes the two steps above safe in either order.</p></div><p>Weigh that against the group-per-tenant model, where onboarding is a <code>ScheduleJob</code> call and none of the above applies.</p><p><strong>A per-tenant thread pool is a real cost.</strong> Under the scheduler-per-tenant model each tenant gets a scheduling loop that wakes on its own idle timer, a thread pool, and — with a persistent store — a connection pool and a cluster check-in. That is fine for tens of tenants and not for thousands.</p><h2 id="observability" tabindex="-1"><a class="header-anchor" href="#observability"><span>Observability</span></a></h2><p>Both signals carry the scheduler name <em>and</em> the scheduler id, so per-tenant dashboards work under the scheduler-per-tenant model with no extra instrumentation — and a tenant running clustered can still be read one node at a time:</p>`,56),e(`ul`,null,[l[40]||=t(`<li><strong>Traces.</strong> <code>quartz.scheduler.name</code> and <code>quartz.scheduler.id</code> are on every span, and the execution span adds <code>quartz.job.group</code>, <code>quartz.job.name</code>, <code>quartz.trigger.group</code>, <code>quartz.trigger.name</code> and <code>quartz.fire.instance.id</code>.</li>`,1),e(`li`,null,[l[38]||=t(`<strong>Metrics.</strong> <code>quartz.scheduler.name</code> and <code>quartz.scheduler.id</code> are on <strong>every</strong> measurement, on every instrument — which is what makes a per-tenant metrics dashboard a <code>group by</code> rather than extra instrumentation. <code>quartz.job.execution.active</code> and <code>quartz.job.execution.duration</code> add <code>quartz.trigger.group</code>, <code>quartz.trigger.name</code>, <code>quartz.job.group</code> and <code>quartz.job.name</code>. The whole set of instruments, and which attributes each carries, is on the `,22),c(h,{to:`/documentation/quartz-4.x/packages/opentelemetry-integration.html#metrics`},{default:i(()=>[...l[37]||=[r(`OpenTelemetry page`,-1)]]),_:1}),l[39]||=r(`.`,-1)])]),l[62]||=t(`<p>Under the group-per-tenant model, <code>quartz.trigger.group</code> and <code>quartz.job.group</code> <strong>are</strong> the tenant, so the same dashboards work by grouping on those instead. That is a good reason to make the group the raw tenant id rather than a decorated string.</p><div class="hint-container warning"><p class="hint-container-title">Cardinality</p><p><code>quartz.job.name</code> and <code>quartz.trigger.name</code> are per job and per trigger. Multiply that by a tenant dimension and a metrics backend can find itself with a series per tenant per trigger. Drop the name tags in a view before they reach the backend unless you know you need them.</p></div><p>The tag names are public constants — <code>ActivityTags.SchedulerName</code>, <code>ActivityTags.TriggerGroup</code> and the rest — so a view or a filter can reference them rather than repeat the strings.</p><h2 id="see-also" tabindex="-1"><a class="header-anchor" href="#see-also"><span>See also</span></a></h2>`,4),e(`ul`,null,[e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/packages/multiple-schedulers.html`},{default:i(()=>[...l[41]||=[r(`Multiple Schedulers`,-1)]]),_:1}),l[42]||=r(` — the mechanics of naming and keying schedulers`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/tutorial/execution-groups.html`},{default:i(()=>[...l[43]||=[r(`Execution Groups`,-1)]]),_:1}),l[44]||=r(` — per-node and cluster-wide thread limits in full`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/tutorial/querying-jobs-and-triggers.html`},{default:i(()=>[...l[45]||=[r(`Querying Jobs and Triggers`,-1)]]),_:1}),l[46]||=r(` — group-filtered listings`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/tutorial/advanced-enterprise-features.html`},{default:i(()=>[...l[47]||=[r(`Clustering`,-1)]]),_:1}),l[48]||=r(` — what a shared database gives you`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/packages/dashboard.html`},{default:i(()=>[...l[49]||=[r(`Dashboard`,-1)]]),_:1}),l[50]||=r(` — the Schedulers page, read-only mode, and how the policy above gates the UI`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/packages/http-api.html#authorizing-per-scheduler`},{default:i(()=>[...l[51]||=[r(`HTTP API`,-1)]]),_:1}),l[52]||=r(` — the same policy on the other surface, and why it answers 403 before 404`,-1)]),e(`li`,null,[c(h,{to:`/documentation/quartz-4.x/migration-guide.html`},{default:i(()=>[...l[53]||=[r(`Migration Guide`,-1)]]),_:1}),l[54]||=r(` — including why a shut-down scheduler cannot be restarted`,-1)])])])}var p=s(u,[[`render`,f]]);export{l as _pageData,p as default};